#include <stdio.h>
struct student {
  int num;
  char name[20];
  int score[3];
  double avg;
};
int main(void)
{
  struct student s[30], t;
  int n, i, j;
  scanf("%d", &n);
  for (i = 0; i < n; i++) {
    scanf("%d%s", &s[i].num, s[i].name);
    for (j = 0; j < 3; j++)
      scanf("%d", &s[i].score[j]);
    s[i].avg = (s[i].score[0] + s[i].score[1]
                + s[i].score[2]) / 3.0;
  }
  for (i = 0; i < n - 1; i++)
    for (j = 0; j < n - 1 - i; j++)
      if (s[j].avg < s[j + 1].avg) {
        t = s[j];
        s[j] = s[j + 1];
        s[j + 1] = t;
      }
  for (i = 0; i < n; i++)
    printf("%d %s %.1f\n", s[i].num, s[i].name,
           s[i].avg);
  return 0;
}

