#include <stdio.h>
#include <stdlib.h>
typedef struct node {
  int data;
  struct node *next;
} NODE;
int main(void)
{
  NODE *head = NULL, *tail = NULL, *p;
  int x, sum = 0;
  scanf("%d", &x);
  while (x != -1) {
    p = (NODE *)malloc(sizeof(NODE));
    if (p == NULL) return 1;
    p->data = x;
    p->next = NULL;
    if (head == NULL) head = p;
    else tail->next = p;
    tail = p;
    scanf("%d", &x);
  }
  if (head == NULL)
    printf("empty\n");
  else {
    for (p = head; p != NULL; p = p->next) {
      if (p != head) printf(" ");
      printf("%d", p->data);
      sum += p->data;
    }
    printf("\nsum=%d\n", sum);
  }
  while (head != NULL) {
    p = head;
    head = head->next;
    free(p);
  }
  return 0;
}

